import re

def trasforma(campi):
    s = re.sub(r'^\s*IT', '', str(campi.get('PartitaIVA') or '').upper())
    s = re.sub(r'[^0-9]', '', s)
    return {'partita_iva': s if len(s) == 11 else None}
